{"path":"effect/main.gd","content":"extends Node
var scene_root: Node
var test_input: Dictionary
var elapsed := 0.0
var frame := 0
var target: Node3D
var projector := Transform3D.IDENTITY
var materials: Array = []
var originals: Array = []
var active := false
var hit_start := 0.0
var target_base := Transform3D.IDENTITY
var receiver = preload("res://effect/receiver.gd").new()
var sampler = preload("res://effect/sampling.gd")

func v(a) -> Vector3:
    return Vector3(a[0], a[1], a[2])

func configure(root: Node, inputs: Dictionary) -> void:
    scene_root = root
    test_input = inputs
    elapsed = 0.0
    frame = 0
    hit_start = float(inputs.hit.time_s)
    receiver.collect(root)
    target = root.get_node_or_null("World/" + str(inputs.hit.target).to_pascal_case())
    active = target != null and inputs.hit.target in inputs.allowed_targets
    if not active: return
    target_base = target.global_transform
    var shader = load("res://effect/projected.gdshader")
    for mesh in target.find_children("*", "MeshInstance3D", true, false):
        for s in mesh.mesh.get_surface_count():
            var base = mesh.get_active_material(s)
            if not base is StandardMaterial3D: continue
            var mat := ShaderMaterial.new()
            mat.shader = shader
            mat.set_shader_parameter("base_color", base.albedo_color)
            mat.set_shader_parameter("has_texture", base.albedo_texture != null)
            if base.albedo_texture: mat.set_shader_parameter("base_texture", base.albedo_texture)
            mat.set_shader_parameter("base_roughness", base.roughness)
            mat.set_shader_parameter("base_metallic", base.metallic)
            mat.set_shader_parameter("base_specular", base.metallic_specular)
            mat.set_shader_parameter("uv_scale", base.uv1_scale)
            mat.set_shader_parameter("uv_offset", base.uv1_offset)
            mat.set_shader_parameter("ink_linear", v(inputs.projector.albedo_linear))
            mat.set_shader_parameter("ink_opacity", inputs.projector.opacity)
            mat.set_shader_parameter("cos_reject", inputs.projector.cos_reject)
            mat.set_shader_parameter("cos_full", inputs.projector.cos_full)
            originals.append([mesh, s, mesh.get_surface_override_material(s), base])
            materials.append(mat)
            mesh.set_surface_override_material(s, mat)
    update_projector()

func update_target_motion() -> void:
    if target == null: return
    var motion: Dictionary = test_input.get("target_motion", {})
    var translation := v(motion.get("translation_m_s", [0,0,0])) * elapsed
    var yaw := deg_to_rad(float(motion.get("yaw_degrees_s", 0.0)) * elapsed)
    target.global_transform = Transform3D(Basis(Vector3.UP, yaw) * target_base.basis, target_base.origin + translation)

func update_projector() -> void:
    if target == null: return
    var n := v(test_input.hit.local_normal).normalized()
    var x := Vector3.UP.cross(n).normalized()
    if x.length_squared() < 0.01: x = Vector3.RIGHT
    var basis := Basis(x, n.cross(x).normalized(), n)
    basis = basis * Basis.from_euler(v(test_input.projector.rotation_degrees) * PI / 180.0)
    basis = basis * Basis.from_scale(v(test_input.projector.scale))
    projector = target.global_transform * Transform3D(basis, v(test_input.hit.local_position) + v(test_input.projector.origin))
    var normal := (projector.basis.inverse().transposed() * Vector3.BACK).normalized()
    for mat in materials:
        mat.set_shader_parameter("world_to_projector", projector.affine_inverse())
        mat.set_shader_parameter("projector_normal", normal)

func step(dt: float) -> void:
    elapsed += dt
    frame += 1
    update_target_motion()
    update_projector()
    if active and elapsed + 0.00000001 >= hit_start + float(test_input.lifetime_s):
        active = false
        for item in originals: item[0].set_surface_override_material(item[1], item[2])

func sample() -> Dictionary:
    receiver.refresh()
    return sampler.capture(self)
"}

{"path":"effect/sampling.gd","content":"extends RefCounted
static func arr(p: Vector3) -> Array: return [p.x,p.y,p.z]

static func capture(effect: Node) -> Dictionary:
    var camera: Camera3D = effect.get_viewport().get_camera_3d()
    var size: Vector2 = effect.get_viewport().get_visible_rect().size
    var pixels: Array = []
    var inv: Transform3D = effect.projector.affine_inverse()
    var settings: Dictionary = effect.test_input.projector
    var ink := Vector3(settings.albedo_linear[0],settings.albedo_linear[1],settings.albedo_linear[2])
    var projection := camera.get_camera_projection()
    for y in 128:
        for x in 128:
            var screen := Vector2((x+0.5)/128.0,(y+0.5)/128.0)*size
            var origin := camera.project_ray_origin(screen)
            var direction := camera.project_ray_normal(screen)
            var hit: Dictionary = effect.receiver.trace(origin,direction)
            var row := {"visible":false,"world_position":null,"projector_local_position":null,"uv":null,"opacity":0.0,"normal":null,"albedo_linear":null}
            if not hit.is_empty():
                var world: Vector3 = hit.position
                var view: Vector3 = camera.global_transform.affine_inverse()*world
                if -view.z >= camera.near and -view.z <= camera.far:
                    var clip := projection * Vector4(view.x,view.y,view.z,1.0)
                    var reverse_depth := 1.0 - (clip.z/clip.w*0.5+0.5)
                    var reconstructed := projection.inverse()*Vector4(clip.x/clip.w,clip.y/clip.w,(1.0-reverse_depth)*2.0-1.0,1.0)
                    world = camera.global_transform*(Vector3(reconstructed.x,reconstructed.y,reconstructed.z)/reconstructed.w)
                    var local: Vector3 = inv*world
                    var normal: Vector3 = hit.normal
                    var opacity := 0.0
                    if effect.active and effect.target.is_ancestor_of(hit.node) and maxf(absf(local.x),maxf(absf(local.y),absf(local.z))) <= 0.5:
                        var cosine := normal.dot(effect.projector.basis.z.normalized())
                        var t := clampf((cosine-float(settings.cos_reject))/(float(settings.cos_full)-float(settings.cos_reject)),0.0,1.0)
                        opacity = float(settings.opacity)*t*t*(3.0-2.0*t)
                    var base: Vector3 = effect.receiver.color_at(hit)
                    var color := base.lerp(ink,opacity)
                    row = {"visible":true,"world_position":arr(world),"projector_local_position":arr(local),"uv":[local.x+0.5,local.y+0.5],"opacity":opacity,"normal":arr(normal),"albedo_linear":arr(color)}
            pixels.append(row)
    return {"step":effect.frame,"elapsed_s":effect.elapsed,"active_target":effect.test_input.hit.target if effect.active else null,"pixel_data":pixels}
"}

{"path":"effect/sampling.gd","content":"extends RefCounted
static func arr(p: Vector3) -> Array: return [p.x,p.y,p.z]

# Reverse-Z reference, near=1 far=0, independent of renderer clip conventions.
static func reverse_depth(z: float, camera: Camera3D) -> float:
    if camera.projection == Camera3D.PROJECTION_ORTHOGONAL:
        return (camera.far-z)/(camera.far-camera.near)
    return (camera.near*camera.far/z-camera.near)/(camera.far-camera.near)

static func capture(effect: Node) -> Dictionary:
    var camera: Camera3D = effect.get_viewport().get_camera_3d()
    var size: Vector2 = effect.get_viewport().get_visible_rect().size
    var pixels: Array = []
    var inv: Transform3D = effect.projector.affine_inverse()
    var settings: Dictionary = effect.test_input.projector
    var ink: Vector3 = effect.v(settings.albedo_linear)
    var projector_normal := (effect.projector.basis.inverse().transposed()*Vector3.BACK).normalized()
    for y in 128:
        for x in 128:
            var screen := Vector2((x+0.5)/128.0,(y+0.5)/128.0)*size
            var origin := camera.project_ray_origin(screen)
            var direction := camera.project_ray_normal(screen)
            var hit: Dictionary = effect.receiver.trace(origin,direction)
            var row := {"visible":false,"world_position":null,"projector_local_position":null,"uv":null,"opacity":0.0,"normal":null,"albedo_linear":null}
            if not hit.is_empty():
                var world: Vector3 = hit.position
                var view: Vector3 = camera.global_transform.affine_inverse()*world
                var depth := reverse_depth(-view.z,camera)
                if depth >= 0.0 and depth <= 1.0:
                    var local: Vector3 = inv*world
                    var normal: Vector3 = hit.normal
                    var opacity := 0.0
                    if effect.active and (effect.target == hit.node or effect.target.is_ancestor_of(hit.node)) and maxf(absf(local.x),maxf(absf(local.y),absf(local.z))) <= 0.5:
                        var cosine := normal.dot(projector_normal)
                        var t := clampf((cosine-float(settings.cos_reject))/maxf(0.000001,float(settings.cos_full)-float(settings.cos_reject)),0.0,1.0)
                        opacity = float(settings.opacity)*t*t*(3.0-2.0*t)
                    var base: Vector3 = effect.receiver.color_at(hit)
                    var color := base.lerp(ink,opacity)
                    row = {"visible":true,"world_position":arr(world),"projector_local_position":arr(local),"uv":[local.x+0.5,local.y+0.5],"opacity":opacity,"normal":arr(normal),"albedo_linear":arr(color)}
            pixels.append(row)
    preload("res://effect/audit.gd").inspect(effect,pixels)
    return {"step":effect.frame,"elapsed_s":effect.elapsed,"active_target":effect.test_input.hit.target if effect.active else null,"pixel_data":pixels}
"}

