{"path":"effect/main.gd","content":"extends Node
var scene_root: Node
var test_input: Dictionary
var elapsed := 0.0
var frame := 0
var target: Node3D
var projector := Transform3D.IDENTITY
var materials: Array = []
var originals: Array = []
var active := false
var event_id := -1
var hit_start := 0.0
var target_base := Transform3D.IDENTITY
var receiver = preload("res://effect/receiver.gd").new()
var sampler = preload("res://effect/sampling.gd")

func v(a) -> Vector3:
    return Vector3(a[0], a[1], a[2])

func configure(root: Node, inputs: Dictionary) -> void:
    scene_root = root
    test_input = inputs
    elapsed = 0.0
    frame = 0
    event_id = int(inputs.hit.event_id)
    hit_start = float(inputs.hit.time_s)
    receiver.collect(root)
    target = root.get_node_or_null("World/" + str(inputs.hit.target).to_pascal_case())
    active = target != null and inputs.hit.target in inputs.allowed_targets
    if not active:
        return
    target_base = target.global_transform
    var shader = load("res://effect/projected.gdshader")
    for mesh in target.find_children("*", "MeshInstance3D", true, false):
        for s in mesh.mesh.get_surface_count():
            var base = mesh.get_active_material(s)
            if not base is StandardMaterial3D:
                continue
            var mat := ShaderMaterial.new()
            mat.shader = shader
            mat.set_shader_parameter("base_color", base.albedo_color)
            mat.set_shader_parameter("has_texture", base.albedo_texture != null)
            if base.albedo_texture:
                mat.set_shader_parameter("base_texture", base.albedo_texture)
            mat.set_shader_parameter("base_roughness", base.roughness)
            mat.set_shader_parameter("base_metallic", base.metallic)
            mat.set_shader_parameter("base_specular", base.metallic_specular)
            mat.set_shader_parameter("uv_scale", base.uv1_scale)
            mat.set_shader_parameter("uv_offset", base.uv1_offset)
            mat.set_shader_parameter("ink_linear", v(inputs.projector.albedo_linear))
            mat.set_shader_parameter("ink_opacity", inputs.projector.opacity)
            mat.set_shader_parameter("cos_reject", inputs.projector.cos_reject)
            mat.set_shader_parameter("cos_full", inputs.projector.cos_full)
            originals.append([mesh, s, mesh.get_surface_override_material(s), base])
            materials.append(mat)
            mesh.set_surface_override_material(s, mat)
    update_projector()

func update_target_motion() -> void:
    if target == null:
        return
    var motion: Dictionary = test_input.get("target_motion", {})
    var translation := v(motion.get("translation_m_s", [0, 0, 0])) * maxf(0.0, elapsed - hit_start)
    var yaw := deg_to_rad(float(motion.get("yaw_degrees_s", 0.0)) * maxf(0.0, elapsed - hit_start))
    # Motion is expressed in world space around the receiver's initial pose.
    target.global_transform = Transform3D(Basis(Vector3.UP, yaw) * target_base.basis, target_base.origin + translation)

func update_projector() -> void:
    if target == null:
        return
    var n := v(test_input.hit.local_normal).normalized()
    var x := Vector3.UP.cross(n).normalized()
    if x.length_squared() < 0.01:
        x = Vector3.RIGHT
    var basis := Basis(x, n.cross(x).normalized(), n)
    basis = basis * Basis.from_euler(v(test_input.projector.rotation_degrees) * PI / 180.0)
    projector = target.global_transform * Transform3D(basis.scaled(v(test_input.projector.scale)), v(test_input.hit.local_position) + v(test_input.projector.origin))
    for mat in materials:
        mat.set_shader_parameter("world_to_projector", projector.affine_inverse())
        mat.set_shader_parameter("projector_normal", projector.basis.z.normalized())

func step(dt: float) -> void:
    elapsed += dt
    frame += 1
    update_target_motion()
    # Refresh the CPU receiver snapshot so traces use the current target pose.
    receiver.collect(scene_root)
    update_projector()
    if active and elapsed + 0.00000001 >= hit_start + float(test_input.lifetime_s):
        active = false
        for item in originals:
            item[0].set_surface_override_material(item[1], item[2])

func sample() -> Dictionary:
    return sampler.capture(self)
"}

{"path":"effect/receiver.gd","content":"extends RefCounted
var faces: Array = []
var textures: Dictionary = {}

func collect(root: Node) -> void:
    faces.clear()
    for node in root.find_children("*", "MeshInstance3D", true, false):
        if not node.is_visible_in_tree() or node.mesh == null:
            continue
        for surface in node.mesh.get_surface_count():
            var arrays = node.mesh.surface_get_arrays(surface)
            var vertices = arrays[Mesh.ARRAY_VERTEX]
            var normals = arrays[Mesh.ARRAY_NORMAL]
            var uvs = arrays[Mesh.ARRAY_TEX_UV]
            var indices = arrays[Mesh.ARRAY_INDEX]
            var material = node.get_active_material(surface)
            var count: int = indices.size() if indices != null and indices.size() > 0 else vertices.size()
            for t in range(0, count, 3):
                var ps: Array = []
                var ns: Array = []
                var ts: Array = []
                for k in 3:
                    var i: int = indices[t+k] if indices != null and indices.size() > 0 else t+k
                    ps.append(vertices[i])
                    ns.append(normals[i] if normals != null and normals.size() > 0 else Vector3.ZERO)
                    ts.append(uvs[i] if uvs != null and uvs.size() > 0 else Vector2.ZERO)
                faces.append({"lp":ps,"ln":ns,"p":[],"n":[],"uv":ts,"material":material,"node":node})
    refresh()
    print("RECEIVER triangles=", faces.size())

func refresh() -> void:
    # Geometry remains in mesh local coordinates; never cache a moving world pose.
    var transforms: Dictionary = {}
    for face in faces:
        var node: MeshInstance3D = face.node
        if not transforms.has(node):
            transforms[node] = [node.global_transform, node.global_basis.inverse().transposed()]
        var transform: Transform3D = transforms[node][0]
        var normals: Basis = transforms[node][1]
        face.p = [transform * face.lp[0], transform * face.lp[1], transform * face.lp[2]]
        face.n = [(normals * face.ln[0]).normalized(), (normals * face.ln[1]).normalized(), (normals * face.ln[2]).normalized()]

func trace(origin: Vector3, direction: Vector3, only: Node = null) -> Dictionary:
    var distance := INF
    var result: Dictionary = {}
    for face in faces:
        if not face.node.is_visible_in_tree():
            continue
        if only != null and not only.is_ancestor_of(face.node) and only != face.node:
            continue
        var a: Vector3 = face.p[0]
        var e1: Vector3 = face.p[1] - a
        var e2: Vector3 = face.p[2] - a
        var h := direction.cross(e2)
        var det := e1.dot(h)
        if absf(det) < 0.0000001:
            continue
        var s := origin - a
        var u := s.dot(h) / det
        if u < -0.000001 or u > 1.000001:
            continue
        var q := s.cross(e1)
        var w := direction.dot(q) / det
        if w < -0.000001 or u+w > 1.000001:
            continue
        var d := e2.dot(q) / det
        if d <= 0.0 or d >= distance:
            continue
        distance = d
        var normal: Vector3 = (face.n[0]*(1.0-u-w) + face.n[1]*u + face.n[2]*w).normalized()
        if normal.length_squared() < 0.1:
            normal = e1.cross(e2).normalized()
        result = {"position":origin+direction*d,"normal":normal,"uv":face.uv[0]*(1.0-u-w)+face.uv[1]*u+face.uv[2]*w,"material":face.material,"node":face.node,"distance":d}
    return result

func color_at(hit: Dictionary) -> Vector3:
    var mat = hit.material
    if not mat is StandardMaterial3D:
        return Vector3.ONE
    var color: Color = mat.albedo_color.srgb_to_linear()
    if mat.albedo_texture != null:
        var id: int = mat.albedo_texture.get_instance_id()
        if not textures.has(id):
            var image: Image = mat.albedo_texture.get_image()
            if image.is_compressed():
                image.decompress()
            textures[id] = image
        var image: Image = textures[id]
        var uv: Vector2 = hit.uv * Vector2(mat.uv1_scale.x,mat.uv1_scale.y) + Vector2(mat.uv1_offset.x,mat.uv1_offset.y)
        var x := posmod(int(floor(uv.x*image.get_width())), image.get_width())
        var y := posmod(int(floor(uv.y*image.get_height())), image.get_height())
        color *= image.get_pixel(x,y).srgb_to_linear()
    return Vector3(color.r,color.g,color.b)
"}

